 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    blocks = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 2 for rr, cc in ((r,c),(r,c+1),(r+1,c),(r+1,c+1))):
                blocks.append((r,c))
    # For each 2x2 marker, rotate its four diagonal colors clockwise,
    # then extend each corner marker diagonally away from the block edge.
    rays = []
    markers = set()
    for r, c in blocks:
        pos = {
            'tl': (r-1, c-1), 'tr': (r-1, c+2),
            'bl': (r+2, c-1), 'br': (r+2, c+2),
        }
        if any(not (0 <= rr < h and 0 <= cc < w) for rr, cc in pos.values()):
            continue
        vals = {k: grid[rr][cc] for k, (rr,cc) in pos.items()}
        if any(v == 0 or v == 2 for v in vals.values()):
            continue
        markers.update(pos.values())
        # Destination corner receives the color from the previous corner.
        rays.extend([
            (pos['tl'], vals['bl'], -1, -1),
            (pos['tr'], vals['tl'], -1, 1),
            (pos['bl'], vals['br'], 1, -1),
            (pos['br'], vals['tr'], 1, 1),
        ])
    for rr, cc in markers:
        out[rr][cc] = 0
    for (rr, cc), color, dr, dc in rays:
        while 0 <= rr < h and 0 <= cc < w:
            out[rr][cc] = color
            rr += dr
            cc += dc
    return out
